import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { delay } from 'rxjs/operators';

export interface BookingRequest {
  name: string;
  lastname: string;
  phone: string;
  email: string;
  date: string;
  time: string;
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  private http = inject(HttpClient);

  /**
   * Set this to your real endpoint.
   *
   * Easiest option — Formspree (free):
   *   1. Create a form at https://formspree.io
   *   2. Paste the endpoint here, e.g. 'https://formspree.io/f/xyzabc'
   *
   * While this is left as the placeholder, submissions are mocked
   * (you'll see a success message, but nothing is sent anywhere).
   */
  private endpoint = 'REPLACE_WITH_YOUR_ENDPOINT';

  submit(data: BookingRequest): Observable<unknown> {
    if (this.endpoint === 'REPLACE_WITH_YOUR_ENDPOINT') {
      // Demo mode — pretend it worked after a short delay.
      console.warn('[BookingService] Demo mode: no endpoint configured.');
      return of({ ok: true }).pipe(delay(800));
    }
    return this.http.post(this.endpoint, data, {
      headers: { Accept: 'application/json' },
    });
  }
}
